def solve(N: int, K: int, S: str) -> int:
    magnets, iron = [], []
    for i in range(N):
        if S[i] == 'M':
            magnets.append(i)
        elif S[i] == 'I':
            iron.append(i)

    if not magnets or not iron:
        return 0

    # Create a grid for storing attraction powers
    grid = [[0] * N for _ in range(N)]

    def calculate_attraction_power(start, end):
        if S[start] == 'X' or S[end] == 'X':
            return float('-inf')
        if start == end:
            return 0
        if grid[start][end] != 0:
            return grid[start][end]
        # Calculate the power considering sheets
        power = K + 1 - abs(end - start)
        for sheet in range(start, end):
            if S[sheet] == ':':
                power -= 1
        grid[start][end] = power
        return power

    # Initialize a dynamic programming table
    dp = [0] * (N + 1)
    for i in range(N):
        for j in range(i + 1, N):
            power = calculate_attraction_power(i, j)
            if power > 0:
                dp[j + 1] = max(dp[j + 1], dp[i] + 1)

    return dp[N]
