def solve(N: int, K: int, S: str) -> int:
    # Find magnets and iron pieces
    magnets = [i for i in range(N) if S[i] == 'M']
    iron_pieces = [i for i in range(N) if S[i] == 'I']

    # Calculate attraction powers
    def power(m, i):
        if S[i] == 'X':
            return 0
        if m == i:
            return K + 1
        return K + 1 - abs(i - m)

    # Greedy algorithm
    chosen_magnets = []
    for m in magnets:
        attracted_iron = 0
        for i in iron_pieces:
            if S[i] == 'I' and power(m, i) > 0:
                attracted_iron += 1
        if attracted_iron > 0:
            chosen_magnets.append(m)

    return len(chosen_magnets)
